    "localFixedCode": "using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using System;
using System.IO;
using System.Globalization;
using System.Collections.Generic;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            const string folder = "Assets/NfsMw/Content/World/Maps/Rockport/Trees/";
            const string progress = "Art/RockportTrees/Source/placement-next.txt";
            var scene = SceneManager.GetActiveScene();
            if (scene.path != "Assets/NfsMw/Scenes/World/RockportMap.unity")
                throw new IOException("Open RockportMap first");
            GameObject root = null;
            foreach (var candidate in scene.GetRootGameObjects())
                if (candidate.name == "Rockport Generated Terrain - 1m Heightmap")
                    root = candidate;
            if (!root || !root.activeSelf)
                throw new IOException("Generated terrain must be active");
            var names = File.ReadAllLines(folder + "prototypes.tsv");
            var tileRows = File.ReadAllLines("Assets/NfsMw/Content/World/Maps/Rockport/Heightmaps/tiles.tsv");
            var placements = File.ReadAllLines(folder + "placements.tsv");
            var terrains = root.GetComponentsInChildren<Terrain>(true);
            int start = File.Exists(progress) ? int.Parse(File.ReadAllText(progress)) : 0, end = Math.Min(start + 6, tileRows.Length), added = 0;
            for (int t = start; t < end; t++)
            {
                var name = tileRows[t].Split('\t')[0];
                Terrain terrain = null;
                foreach (var candidate in terrains)
                    if (candidate.name == name)
                        terrain = candidate;
                if (!terrain)
                    throw new IOException(name);
                var data = terrain.terrainData;
                var prototypes = new List<TreePrototype>();
                var instances = new List<TreeInstance>();
                var oldPrototypes = data.treePrototypes;
                var oldIndices = new Dictionary<int, int>();
                for (int i = 0; i < oldPrototypes.Length; i++)
                    if (!AssetDatabase.GetAssetPath(oldPrototypes[i].prefab).StartsWith(folder + "Prefabs/"))
                    {
                        oldIndices.Add(i, prototypes.Count);
                        prototypes.Add(oldPrototypes[i]);
                    }

                foreach (var old in data.treeInstances)
                    if (oldIndices.TryGetValue(old.prototypeIndex, out int id))
                    {
                        var kept = old;
                        kept.prototypeIndex = id;
                        instances.Add(kept);
                    }

                var localIndices = new Dictionary<int, int>();
                foreach (var line in placements)
                {
                    var cols = line.Split('\t');
                    if (cols[0] != name)
                        continue;
                    int sourceIndex = int.Parse(cols[1]);
                    if (!localIndices.TryGetValue(sourceIndex, out int localIndex))
                    {
                        var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(folder + "Prefabs/" + names[sourceIndex] + ".prefab");
                        if (!prefab || !prefab.GetComponent<LODGroup>())
                            throw new IOException("Missing tree prefab " + sourceIndex);
                        localIndex = prototypes.Count;
                        prototypes.Add(new TreePrototype{prefab = prefab, bendFactor = 0});
                        localIndices.Add(sourceIndex, localIndex);
                    }

                    var world = new Vector3(float.Parse(cols[2], CultureInfo.InvariantCulture), float.Parse(cols[3], CultureInfo.InvariantCulture), float.Parse(cols[4], CultureInfo.InvariantCulture));
                    var local = world - terrain.transform.position;
                    var size = data.size;
                    var position = new Vector3(local.x / size.x, local.y / size.y, local.z / size.z);
                    if (position.x < 0 || position.x > 1 || position.y < 0 || position.y > 1 || position.z < 0 || position.z > 1)
                        throw new IOException("Tree outside terrain " + cols[8]);
                    instances.Add(new TreeInstance{position = position, prototypeIndex = localIndex, rotation = float.Parse(cols[5], CultureInfo.InvariantCulture), widthScale = float.Parse(cols[6], CultureInfo.InvariantCulture), heightScale = float.Parse(cols[7], CultureInfo.InvariantCulture), color = Color.white, lightmapColor = Color.white});
                    added++;
                }

                data.treePrototypes = prototypes.ToArray();
                data.SetTreeInstances(instances.ToArray(), false);
                terrain.drawTreesAndFoliage = true;
                terrain.treeDistance = 12000;
                terrain.treeBillboardDistance = 12000;
                terrain.treeMaximumFullLODCount = 20000;
                terrain.Flush();
                EditorUtility.SetDirty(data);
                EditorUtility.SetDirty(terrain);
            }

            AssetDatabase.SaveAssets();
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            File.WriteAllText(progress, end.ToString());
            result.Log("Added " + added + " authored tree/group instances; tiles " + end + " / " + tileRows.Length + " complete.");
        }
    }
}",
    "result": "Command executed successfully."
  }
}

